query:
for $t in /*/*[starts-with(name(), 'PK.800.01_')]
let $v := string($t/@VRG)
let $stamm := /*/*[starts-with(name(), 'PK.000.01_')][@VRG = $v]
order by xs:integer(($v[. castable as xs:integer], 0)[1])
return string-join(('VRG ' || $v, normalize-space($stamm/*[RowCode = 'R000-110']/Wert), 'Art ' || normalize-space($stamm/*[RowCode = 'R000-120']/Wert), format-number(sum($t/*[normalize-space(RowCode) = 'R800-800']/Wert[. castable as xs:decimal] ! xs:decimal(.)), '#,##0.00')), ' | ')

for $t in /*/*[starts-with(name(), 'PK.006.02.01.01_')]
let $v := string($t/@VRG)
let $info := /*/*[starts-with(name(), 'PK.006.02.01.02_')][@VRG = $v]/Datenpunkt
for $p in $t/Datenpunkt
let $cic := normalize-space(($info[Wert_C0010PK = $p/Wert_C0010PK]/Wert_C0230)[1])
group by $v, $cat := substring($cic, 3, 1)
order by number($v), $cat
return string-join(('VRG ' || $v, 'CIC ##' || $cat || '#', count($p) || ' positions', format-number(sum($p/Wert_C1110PK[. castable as xs:decimal] ! xs:decimal(.)), '#,##0.00')), ' | ')

for $d in /*/*[starts-with(name(), 'PK.006.03_')]/Datenpunkt
let $mw := ($d/Wert_C1110PK[. castable as xs:decimal] ! xs:decimal(.), 0)[1]
group by $v := string($d/../@VRG), $fund := normalize-space($d/Wert_C0010PK)
let $total := sum($mw)
let $open := sum(for $x in $d[normalize-space(Wert_C0030PK) eq '4'] return ($x/Wert_C1110PK[. castable as xs:decimal] ! xs:decimal(.), 0)[1])
order by number($v), $open descending
return string-join(('VRG ' || $v, $fund, format-number($total, '#,##0.00'), format-number($open, '#,##0.00'), if ($total ne 0) then format-number($open div $total * 100, '0.00') || ' %' else '-'), ' | ')
